style.css:
@-moz-document domain("roblox.com") {
/* Fundo principal do site com a imagem em alta definição */
  body, .rbx-body, .content, .main-layout, .content-wrapper, .footer {
    background-image: url('https://ibb.co') !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: #15161a !important;
  }

  /* Deixa as caixas de jogos e menus semi-transparentes para o Invencível aparecer atrás */
  .section, .section-content, .container-main, .container-header, .game-card, .item-card, .vngle-table-container, #container-main, .grid-item-container {
    background-color: rgba(21, 22, 26, 0.6) !important;
    background: rgba(21, 22, 26, 0.6) !important;
    border: none !important;
  }

  /* Cabeçalho superior do Roblox (Azul do traje) */
  .navbar-default, .rbx-header, .notification-stream-base {
    background-color: #1e6bbb !important;
  }

  /* Menu lateral esquerdo adaptado */
  .left-navigation, .menu-sidebar, #navigation {
    background-color: rgba(15, 16, 20, 0.85) !important;
  }

  /* Botões personalizados */
  .btn-secondary-md, .btn-primary-md, .btn-to-all {
    background-color: #15161a !important;
    color: #1e6bbb !important;
    border: 1px solid #1e6bbb !important;
  }
  
  /* Mantém todas as letras brancas e legíveis */
  h1, h2, h3, h4, h5, h6, span, p, a, .text, .text-name {
    color: #ffffff !important;
  }
}
